<?php require_once __DIR__.'/../includes/admin-auth.php';$pageTitle='My profile';$err=[];$s=$pdo->prepare('SELECT * FROM admin_users WHERE id=?');$s->execute([$_SESSION['admin_id']]);$a=$s->fetch();if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=trim($_POST['name']??'');$old=$_POST['current_password']??'';$new=$_POST['new_password']??'';if($m=v_name($name))$err[]=$m;if($new!==''||$old!==''){if($old==='')$err[]='Enter your current password to change it.';elseif(!password_verify($old,$a['password_hash']))$err[]='Current password is incorrect.';if($m=v_password($new,12))$err[]=$m;elseif($new!==($_POST['confirm_password']??''))$err[]='New password and confirmation do not match.';}if(!$err){if($new!=='')$pdo->prepare('UPDATE admin_users SET name=?,password_hash=? WHERE id=?')->execute([$name,password_hash($new,PASSWORD_DEFAULT),$a['id']]);else$pdo->prepare('UPDATE admin_users SET name=? WHERE id=?')->execute([$name,$a['id']]);$_SESSION['admin_name']=$name;log_action($pdo,'admin.profile.update','Updated own profile');flash('success','Profile updated.');redirect('profile.php');}}require __DIR__.'/../includes/admin-layout.php'; ?><div class="panel" style="max-width:700px"><?=render_errors($err)?><form method="post" data-validate novalidate><?=csrf_field()?><div class="mb-3"><label class="form-label" for="name">Name</label><input class="form-control" id="name" name="name" required minlength="2" maxlength="60" data-rule="name" value="<?=e($_POST['name']??$a['name'])?>"></div><div class="mb-3"><label class="form-label">Email</label><input class="form-control" value="<?=e($a['email'])?>" disabled></div><hr><h2 class="h5">Change password (optional)</h2><div class="mb-3"><label class="form-label" for="current_password">Current password</label><input class="form-control" id="current_password" type="password" name="current_password" maxlength="72" autocomplete="current-password" data-required-if="#new_password"></div><div class="mb-3"><label class="form-label" for="new_password">New password</label><input class="form-control" id="new_password" type="password" name="new_password" minlength="12" maxlength="72" data-rule="strongpass" data-strength data-required-if="#current_password" autocomplete="new-password"><div class="form-text">Leave both password fields empty to keep your current password.</div></div><div class="mb-4"><label class="form-label" for="confirm_password">Confirm new password</label><input class="form-control" id="confirm_password" type="password" name="confirm_password" maxlength="72" data-match="#new_password" data-required-if="#new_password" autocomplete="new-password"></div><button class="btn btn-primary">Save profile</button></form></div><?php require __DIR__.'/../includes/admin-footer.php'; ?>
